use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{ApplyResult, PluginCapabilities, StateAction, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use serde_json::json;
use serde_json::Value as JsonValue;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use reqwest::Client;

/// EMQX configuration.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, Default)]
pub struct EmqxConfig {
    /// Enable EMQX management API
    pub enabled: bool,
    /// EMQX API host
    pub host: String,
    /// EMQX API port
    pub port: u16,
    /// EMQX API username
    pub username: String,
    /// EMQX API password
    pub password: String,
    /// EMQX API base path (usually /api/v5)
    #[serde(default = "default_api_path")]
    pub api_path: String,
}

fn default_api_path() -> String {
    "/api/v5".to_string()
}

/// EMQX client information.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxClient {
    /// Client ID
    pub clientid: String,
    /// Username
    pub username: Option<String>,
    /// IP address
    pub ipaddress: String,
    /// Port
    pub port: u16,
    /// Protocol (MQTT, CoAP, etc.)
    pub proto: String,
    /// Connected at (timestamp)
    pub connected_at: u64,
    /// Disconnected at (timestamp, 0 if connected)
    pub disconnected_at: u64,
    /// Is connected
    pub connected: bool,
    /// Node
    pub node: String,
}

/// EMQX state.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxState {
    /// Software name (emqx)
    pub software: String,
    /// Version string
    pub version: String,
    /// Whether emqx is installed
    pub installed: bool,
    /// Whether the emqx service is running
    pub running: bool,
    /// EMQX configuration
    pub config: EmqxConfig,
    /// List of clients
    pub clients: Vec<EmqxClient>,
    /// Available tools
    #[schemars(with = "serde_json::Value")]
    pub tools: JsonValue,
}

pub struct EmqxPlugin {
    config: EmqxConfig,
    client: Arc<Mutex<Option<Client>>>,
}

impl EmqxPlugin {
    pub fn new(config: EmqxConfig) -> Self {
        Self {
            config,
            client: Arc::new(Mutex::new(None)),
        }
    }

    /// Get or create the HTTP client
    async fn get_client(&self) -> Result<Client> {
        let mut lock = self.client.lock().await;
        if lock.is_none() {
            let client = Client::builder()
                .user_agent("opdbus-emqx-plugin")
                .build()
                .context("Failed to create HTTP client")?;
            *lock = Some(client);
        }
        Ok(lock.clone().unwrap())
    }

    /// Check if emqx is installed via direct file check
    async fn check_emqx_installed() -> Result<bool> {
        Ok(std::path::Path::new("/usr/bin/emqx").exists()
            || std::path::Path::new("/usr/local/bin/emqx").exists())
    }

    /// Check if emqx service is running via D-Bus (s6)
    async fn check_emqx_running() -> Result<bool> {
        use zbus::{Connection, Proxy};
        if !std::path::Path::new("/run/s6-rc").exists() && !std::path::Path::new("/run/service").exists() {
            return Err(anyhow::anyhow!("s6 runtime not found"));
        }
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        let proxy: Proxy<'_, zblocking::BlockingProxy> = Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;
        let result: String = proxy
            .call("is_active", &( "emqx", ))
            .await?;
        Ok(result == "active")
    }

    /// Get the base URL for the EMQX API
    fn api_base_url(&self) -> String {
        format!(
            "http://{}:{}{}",
            self.config.host, self.config.port, self.config.api_path
        )
    }

    /// Fetch clients from EMQX API
    async fn fetch_clients(&self) -> Result<Vec<EmqxClient>> {
        let client = self.get_client().await?;
        let url = format!("{}/clients", self.api_base_url());
        let resp = client
            .get(&url)
            .basic_auth(&self.config.username, Some(&self.config.password))
            .send()
            .await?
            .error_for_status()?;
        let data: serde_json::Value = resp.json().await?;
        // EMQX API returns { data: [], meta: { ... } }
        let clients = data
            .get("data")
            .and_then(|d| d.as_array())
            .unwrap_or(&vec![])
            .iter()
            .filter_map(|c| {
                serde_json::from_value::<EmqxClient>(c.clone()).ok()
            })
            .collect();
        Ok(clients)
    }

    /// Get current state by querying EMQX API
    async fn current_state(&self) -> Result<EmqxState> {
        let installed = Self::check_emqx_installed().await?;
        let running = Self::check_emqx_running().await?;
        let clients = if self.config.enabled && installed && running {
            self.fetch_clients().await?
        } else {
            vec![]
        };
        Ok(EmqxState {
            software: "emqx".to_string(),
            version: "5.0.0".to_string(), // TODO: get from API
            installed,
            running,
            config: self.config.clone(),
            clients,
            tools: json!([
                {
                    "name": "emqx.list_clients",
                    "description": "List all connected MQTT clients",
                    "parameters": {
                        "type": "object",
                        "properties": {},
                        "additionalProperties": false
                    }
                },
                {
                    "name": "emqx.get_client",
                    "description": "Get details of a specific MQTT client",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "clientid": {
                                "type": "string",
                                "description": "The client ID"
                            }
                        },
                        "required": ["clientid"]
                    }
                }
            ]),
        })
    }
}

#[async_trait]
impl StatePlugin for EmqxPlugin {
    fn name(&self) -> &'static str {
        "emqx"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let root = schemars::schema_for!(EmqxState);
        let root_value = serde_json::to_value(&root).expect("schemars schema serializes to JSON");
        let mut schema = super::schemars_adapter::plugin_schema_from_json(
            "emqx",
            "1.0.0",
            "EMQX MQTT broker state and management API",
            &root_value,
        );
        super::schemars_adapter::apply_state_defaults(&mut schema, &self.current_state().await.ok().unwrap_or_default().into());
        // Add methods
        use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
        use super::plugin_scaffold_helpers::AckOutput;
        use op_state_store::SideEffect;

        // list_clients: no input, returns list of clients
        schema.methods.insert(
            "list_clients".to_string(),
            method_decl_from_schemars_with_output::<(), Vec<EmqxClient>>(
                "list_clients",
                SideEffect::Read,
                true,
                "obs.emqx.clients.list@v1",
                "obs.emqx.clients.list@v1",
            ),
        );

        // get_client: takes clientid, returns client info
        schema.methods.insert(
            "get_client".to_string(),
            method_decl_from_schemars_with_output::<String, EmqxClient>(
                "get_client",
                SideEffect::Read,
                true,
                "obs.emqx.client.get@v1",
                "obs.emqx.client.get@v1",
            ),
        );

        Some(schema)
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let mut actions = Vec::new();
        let current_state = self.current_state().await?;
        let desired_state: EmqxState = serde_json::from_value(desired.clone())?;

        // Check if we need to enable/disable the service
        if current_state.config.enabled != desired_state.config.enabled {
            if desired_state.config.enabled {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "start_service",
                        "service": "emqx"
                    }),
                });
            } else {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "stop_service",
                        "service": "emqx"
                    }),
                });
            }
        }

        // For now, we don't implement client management via this plugin
        // (since clients are MQTT connections, not managed via REST)
        // But we could add actions for kicking clients, etc.

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: Default::default(),
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::[];

        for action in &diff.actions {
            if let StateAction::Create { resource, config } = action {
                if resource == "emqx_service" {
                    let action = config.get("action").and_then(|v| v.as_str()).unwrap_or("");
                    let service = config.get("service").and_then(|v| v.as_str()).unwrap_or("");
                    if action == "start_service" && service == "emqx" {
                        // Start emqx service via D-Bus (s6)
                        match self.start_emqx_service().await {
                            Ok(_) => changes_applied.push("Started EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to start EMQX service: {}", e)),
                        }
                    } else if action == "stop_service" && service == "emqx" {
                        // Stop emqx service via D-Bus (s6)
                        match self.stop_emqx_service().await {
                            Ok(_) => changes_applied.push("Stopped EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to stop EMQX service: {}", e)),
                        }
                    }
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<op_state::Checkpoint> {
        Ok(op_state::Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: self.current_state().await?.into(),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &op_state::Checkpoint) -> Result<()> {
        // Rollback would involve reverting service state, etc.
        Err(anyhow::anyhow!("EMQX plugin rollback not implemented"))
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }

    /// Start the EMQX service via s6 D-Bus
    async fn start_emqx_service(&self) -> Result<()> {
        use zbus::{Connection, Proxy};
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        let proxy: Proxy<'_, zblocking::BlockingProxy> = Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;
        let (success, msg): (bool, String) = proxy
            .call("start", &( "emqx", ))
            .await?;
        if !success {
            return Err(anyhow::anyhow!("Failed to start emqx service: {}", msg));
        }
        Ok(())
    }

    /// Stop the EMQX service via s6 D-Bus
    async fn stop_emqx_service(&self) -> Result<()> {
        use zbus::{Connection, Proxy};
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        let proxy: Proxy<'_, zblocking::BlockingProxy> = Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;
        let (success, msg): (bool, String) = proxy
            .call("stop", &( "emqx", ))
            .await?;
        if !success {
