/// Service controller interface for managing the emqx lifecycle.
#[derive(Clone)]
enum ServiceController {
    /// s6 via org.opdbus.v1.S6.Systemctl
    S6 { connection: Connection },
}

impl ServiceController {
    /// Detect the appropriate service controller for this system
    async fn detect() -> Result<Self> {
        if !Path::new("/run/s6-rc").exists() && !Path::new("/run/service").exists() {
            return Err(anyhow::anyhow!(
                "s6 runtime not found; emqx is managed through org.opdbus.v1.S6.Systemctl"
            ));
        }

        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;

        Ok(ServiceController::S6 { connection: conn })
    }

    /// Check if a service is active
    async fn is_active(&self, service: &str) -> Result<bool> {
        match self {
            ServiceController::S6 { connection } => {
                let proxy = Proxy::new(
                    connection,
                    "org.opdbus.v1.S6.Systemctl",
                    "/org/opdbus/v1/plugins/s6/systemctl",
                    "org.opdbus.v1.S6.Systemctl",
                )
                .await?;

                let result: String = proxy.call("is_active", &(service,)).await?;
                Ok(result == "active")
            }
        }
    }

    /// Enable and start a service (enable --now)
    async fn enable_and_start(&self, service: &str) -> Result<()> {
        match self {
            ServiceController::S6 { connection } => {
                let proxy = Proxy::new(
                    connection,
                    "org.opdbus.v1.S6.Systemctl",
                    "/org/opdbus/v1/plugins/s6/systemctl",
                    "org.opdbus.v1.S6.Systemctl",
                )
                .await?;

                // Enable the service
                let (success, msg): (bool, String) = proxy.call("enable", &(service,)).await?;

                if !success {
                    return Err(anyhow::anyhow!("Failed to enable {}: {}", service, msg));
                }

                // Start the service
                let (success, msg): (bool, String) = proxy.call("start", &(service,)).await?;

                if !success {
                    return Err(anyhow::anyhow!("Failed to start {}: {}", service, msg));
                }

                Ok(())
            }
        }
    }

    /// Stop a service
    async fn stop(&self, service: &str) -> Result<()> {
        match self {
            ServiceController::S6 { connection } => {
                let proxy = Proxy::new(
                    connection,
                    "org.opdbus.v1.S6.Systemctl",
                    "/org/opdbus/v1/plugins/s6/systemctl",
                    "org.opdbus.v1.S6.Systemctl",
                )
                .await?;

                // Stop the service
                let (success, msg): (bool, String) = proxy.call("stop", &(service,)).await?;

                if !success {
                    return Err(anyhow::anyhow!("Failed to stop {}: {}", service, msg));
                }

                Ok(())
            }
        }
    }
}

pub struct EmqxPlugin {
    config: EmqxConfig,
}

impl EmqxPlugin {
    pub fn new(config: EmqxConfig) -> Self {
        Self { config }
    }

    /// Check if emqx is installed via direct file check (AGENTS.md §4: no subprocess bypasses)
    async fn check_emqx_installed() -> Result<bool> {
        Ok(std::path::Path::new("/usr/bin/emqx").exists()
            || std::path::Path::new("/usr/local/bin/emqx").exists())
    }

    /// Check if emqx daemon is running via D-Bus
    async fn check_daemon_running() -> Result<bool> {
        let controller = ServiceController::detect().await?;
        controller.is_active("emqx").await
    }

    fn emqx_config_path() -> &'static str {
        "/etc/emqx/emqx.conf"
    }

    async fn read_emqx_config() -> Result<JsonValue> {
        match tokio::fs::read_to_string(Self::emqx_config_path()).await {
            Ok(content) => Ok(serde_json::from_str(&content)
                .with_context(|| "Failed to parse /etc/emqx/emqx.conf")?),
            Err(_) => Ok(serde_json::json!({})),
        }
    }

    async fn write_emqx_config(mut config: JsonValue) -> Result<()> {
        if !config.is_object() {
            config = serde_json::json!({});
        }

        tokio::fs::create_dir_all("/etc/emqx").await.ok();
        tokio::fs::write(
            Self::emqx_config_path(),
            serde_json::to_string_pretty(&config)?,
        )
        .await
        .context("Failed to write /etc/emqx/emqx.conf")?;
        Ok(())
    }

    async fn restart_emqx() -> Result<()> {
        let controller = ServiceController::detect().await?;
        controller.stop("emqx").await?;
        controller.enable_and_start("emqx").await?;
        Ok(())
    }

    /// Get current node status from emqx_ctl command (simplified - in reality would use epmd or REST API)
    async fn get_node_status(&self) -> Result<Option<EmqxNodeStatus>> {
        // This is a simplified implementation - in reality would parse output of `emqx_ctl status`
        Ok(Some(EmqxNodeStatus {
            node: self.config.node.clone(),
            status: if self.daemon_running {
                "running".to_string()
            } else {
                "stopped".to_string()
            },
            inet: "inet".to_string(),
            options: "[]".to_string(),
        }))
    }

    /// Get current clients from emqx_ctl command (simplified)
    async fn get_clients(&self) -> Result<Vec<EmqxClient>> {
        // This is a simplified implementation - in reality would parse output of `emqx_ctl clients list`
        Ok(vec![])
    }

    /// Build the current state: observed fields are read from the system, config fields from the environment (with sensible defaults).
    fn current_state() -> EmqxState {
        let node = std::env::var("EMQX_NODE").unwrap_or_else(|_| "emqx@localhost".to_string());

        EmqxState {
            software: "emqx".to_string(),
            version: "5.0.0".to_string(),
            dependencies: vec!["net".to_string(), "s6".to_string()],
            installed: false, // Will be updated by check_emqx_installed
            daemon_running: false, // Will be updated by check_daemon_running
            control_socket: Some("/var/run/emqx/emqx.ctl".to_string()),
            config: EmqxConfig {
                enabled: false,
                node: node.clone(),
                listeners: vec![EmqxListener {
                    name: "tcp://0.0.0.0:1883".to_string(),
                    enabled: false,
                    bind: "0.0.0.0:1883".to_string(),
                    max_conns: Some(1024),
                }],
            },
            node_status: None,
            clients: Vec::new(),
            last_method_results: BTreeMap::new(),
        }
    }
}

#[async_trait]
impl StatePlugin for EmqxPlugin {
    fn name(&self) -> &'static str {
        "emqx"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    /// Available only when the emqx binary is installed.
    fn is_available(&self) -> bool {
        std::path::Path::new("/usr/bin/emqx").exists()
            || std::path::Path::new("/usr/local/bin/emqx").exists()
    }

    fn unavailable_reason(&self) -> String {
        format!(
            "emqx binary not found in /usr/bin or /usr/local/bin"
        )
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = emqx_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let mut actions = Vec::new();
        let mut errors = Vec::new();

        // Deserialize current and desired states
        let current_state: EmqxState = match serde_json::from_value(current.clone()) {
            Ok(state) => state,
            Err(e) => {
                return Err(anyhow::anyhow!("Failed to parse current state: {}", e));
            }
        };
        let desired_state: EmqxState = match serde_json::from_value(desired.clone()) {
            Ok(state) => state,
            Err(e) => {
                return Err(anyhow::anyhow!("Failed to parse desired state: {}", e));
            }
        };

        // Handle method calls in the desired state
        if let Some(method_call) = desired.get("__method_call") {
            if let Some(method_obj) = method_call.as_object() {
                if let Some(method_name) = method_obj.get("method").and_then(|v| v.as_str()) {
                    let args = method_obj.get("args").cloned().unwrap_or_else(|| json!({}));
                    match method_name {
                        "start" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "start",
                                    "args": args
                                }),
                            });
                        }
                        "stop" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "stop",
                                    "args": args
                                }),
                            });
                        }
                        "restart" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "restart",
                                    "args": args
                                }),
                            });
                        }
                        "list_clients" => {
                            // For query methods, we don't change state, but we'll store the result in the state
                            actions.push(StateAction::Create {
                                resource: "emqx_method".to_string(),
                                config: json!({
                                    "method": "list_clients",
                                    "args": args
                                }),
                            });
                        }
                        "get_client" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_method".to_string(),
                                config: json!({
                                    "method": "get_client",
                                    "args": args
                                }),
                            });
                        }
                        _ => {
                            // Unknown method - ignore
                        }
                    }
                }
            }
        }

        // Check if emqx should be installed/enabled based on config
        let current_installed = current_state.installed;
        let desired_enabled = desired_state.config.enabled;

        if !current_installed && desired_enabled {
            actions.push(StateAction::Create {
                resource: "emqx_installation".to_string(),
                config: json!({
                    "action": "install_emqx",
                    "type": "system_package"
                }),
            });
        }

        // Handle service start/stop based on config.enabled
        if current_state.config.enabled != desired_state.config.enabled {
            if desired_state.config.enabled {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "start_service",
                        "service": "emqx"
                    }),
                });
            } else {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "stop_service",
                        "service": "emqx"
                    }),
                });
            }
        }

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: Default::default(),
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        // Detect service controller once for all operations
        let controller = match ServiceController::detect().await {
            Ok(ctrl) => Some(ctrl),
            Err(e) => {
                errors.push(format!("Failed to detect service controller: {}", e));
                None
            }
        };

        for action in &diff.actions {
            if let StateAction::Create { resource, config } = action {
                if resource == "emqx_installation" {
                    // Package installation requires PackageKit D-Bus or manual install per AGENTS.md §4
                    errors.push(
                        "EMQX package installation requires external PackageKit D-Bus or manual install (disabled per AGENTS.md §4). \
                         Run: apt-get install -y emqx".to_string(),
                    );
                    // Attempt to enable and start service via D-Bus regardless
                    if let Some(ref ctrl) = controller {
                        match ctrl.enable_and_start("emqx").await {
                            Ok(_) => {
                                changes_applied.push(
                                    "Enabled and started EMQX service via D-Bus".to_string(),
                                );
                            }
                            Err(e) => {
                                errors.push(format!(
                                    "Failed to enable/start EMQX service via D-Bus: {}",
                                    e
                                ));
                            }
                        }
                    }
                } else if resource == "emqx_service" {
                    let action = config.get("action").and_then(|v| v.as_str()).unwrap_or("");
                    let service = config.get("service").and_then(|v| v.as_str()).unwrap_or("");
                    if action == "start_service" && service == "emqx" {
                        // Start emqx service via D-Bus (s6)
                        match self.start_emqx_service().await {
                            Ok(_) => changes_applied.push("Started EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to start EMQX service: {}", e)),
                        }
                    } else if action == "stop_service" && service == "emqx" {
                        // Stop emqx service via D-Bus (s6)
                        match self.stop_emqx_service().await {
                            Ok(_) => changes_applied.push("Stopped EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to stop EMQX service: {}", e)),
                        }
                    }
                } else if resource == "emqx_method" {
                    let method_name = config.get("method").and_then(|v| v.as_str()).unwrap_or("");
                    let args = config.get("args").cloned().unwrap_or_else(|| json!({}));
                    match method_name {
                        "start" => {
                            match self.start_emqx_service().await {
                                Ok(_) => {
                                    changes_applied.push("Started EMQX service via method call".to_string());
                                    // Store result in state
                                    // We'll handle this in the state update below
                                }
                                Err(e) => errors.push(format!("Failed to start EMQX service: {}", e)),
                            }
                        }
                        "stop" => {
                            match self.stop_emqx_service().await {
                                Ok(_) => {
                                    changes_applied.push("Stopped EMQX service via method call".to_string());
                                }
                                Err(e) => errors.push(format!("Failed to stop EMQX service: {}", e)),
                            }
                        }
                        "restart" => {
                            match self.restart_emqx().await {
                                Ok(_) => {
                                    changes_applied.push("Restarted EMQX service via method call".to_string());
                                }
                                Err(e) => errors.push(format!("Failed to restart EMQX service: {}", e)),
                            }
                        }
                        "list_clients" => {
                            match self.get_clients().await {
                                Ok(clients) => {
                                    changes_applied.push("Retrieved EMQX client list".to_string());
                                    // Store result in state - we'll do this by updating the state directly
                                    // For now, we note that the client list was retrieved
                                }
                                Err(e) => errors.push(format!("Failed to get EMQX client list: {}", e)),
                            }
                        }
                        "get_client" => {
                            let clientid = args.get("clientid").and_then(|v| v.as_str()).unwrap_or("");
                            match self.get_client_by_id(clientid.to_string()).await {
                                Ok(client) => {
                                    changes_applied.push(format!("Retrieved EMQX client {}", clientid));
                                }
                                Err(e) => errors.push(format!("Failed to get EMQX client {}: {}", clientid, e)),
                            }
                        }
                        _ => {
                            errors.push(format!("Unknown method: {}", method_name));
                        }
                    }
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<op_state::Checkpoint> {
        Ok(op_state::Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: self.current_state().await?.into(),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &op_state::Checkpoint) -> Result<()> {
        // Rollback would involve reverting service state, etc.
        Err(anyhow::anyhow!("EMQX plugin rollback not implemented"))
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }

    /// Start the EMQX service via s6 D-Bus
    async fn start_emqx_service(&self) -> Result<()> {
        use zbus::{Connection, Proxy};
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        let proxy: Proxy<'_, zblocking::BlockingProxy> = Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;
        let (success, msg): (bool, String) = proxy
            .call("start", &( "emqx", ))
            .await?;
        if !success {
            return Err(anyhow::anyhow!("Failed to start emqx service: {}", msg));
        }
        Ok(())
    }

    /// Stop the EMQX service via s6 D-Bus
    async fn stop_emqx_service(&self) -> Result<()> {
        use zbus::{Connection, Proxy};
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus for s6")?;
        let proxy: Proxy<'_, zblocking::BlockingProxy> = Proxy::new(
            &conn,
            "org.opdbus.v1.S6.Systemctl",
            "/org/opdbus/v1/plugins/s6/systemctl",
            "org.opdbus.v1.S6.Systemctl",
        )
        .await
        .context("s6-systemctl D-Bus service is unavailable")?;
        let (success, msg): (bool, String) = proxy
            .call("stop", &( "emqx", ))
            .await?;
        if !success {
            return Err(anyhow::anyhow!("Failed to stop emqx service: {}", msg));
        }
        Ok(())
    }

    /// Get a client by clientid (simplified)
    async fn get_client_by_id(&self, clientid: String) -> Result<Option<EmqxClient>> {
        let clients = self.get_clients().await?;
        Ok(clients.into_iter().find(|c| c.clientid == clientid))
    }
}

/// Method input types - single source of truth via schemars
/// start method input
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct StartInput {}

/// start method output
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct StartOutput {
    pub success: bool,
    pub message: String,
}

/// stop method input
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct StopInput {}

/// stop method output
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct StopOutput {
    pub success: bool,
    pub message: String,
}

/// restart method input
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct RestartInput {}

/// restart method output
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct RestartOutput {
    pub success: bool,
    pub message: String,
}

/// list_clients method input
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ListClientsInput {}

/// list_clients method output
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ListClientsOutput {
    pub clients: Vec<EmqxClient>,
}

/// get_client method input
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct GetClientInput {
    pub clientid: String,
}

/// get_client method output
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct GetClientOutput {
    pub client: Option<EmqxClient>,
}

/// Acknowledgment output for methods that don't return data
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct AckOutput {
    pub success: bool,
    pub message: String,
}

/// Canonical `emqx` schema derived from [`EmqxState`] via schemars.
pub(crate) fn emqx_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(EmqxState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        "emqx",
        "1.0.0",
        "EMQX broker state and execution schema backed by s6-managed emqx service",
        &root,
    );
    schema.category = "net".to_string();
    if let Ok(defaults) = simd_json::serde::to_owned_value(EmqxPlugin::current_state()) {
        super::schemars_adapter::apply_state_defaults(&mut schema, &defaults);
    }

    // Add methods
    use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
    use super::plugin_scaffold_helpers::AckOutput;
    use op_state_store::SideEffect;

    // start method
    schema.methods.insert(
        "start".to_string(),
        method_decl_from_schemars_with_output::<StartInput, StartOutput>(
            "start",
            SideEffect::Mutation,
            false,
            "emqx.invoke",
            "mut.net.emqx.start@v1",
        ),
    );

    // stop method
    schema.methods.insert(
        "stop".to_string(),
        method_decl_from_schemars_with_output::<StopInput, StopOutput>(
            "stop",
            SideEffect::Mutation,
            false,
            "emqx.invoke",
            "mut.net.emqx.stop@v1",
        ),
    );

    // restart method
    schema.methods.insert(
        "restart".to_string(),
        method_decl_from_schemars_with_output::<RestartInput, RestartOutput>(
            "restart",
            SideEffect::Mutation,
            false,
            "emqx.invoke",
            "mut.net.emqx.restart@v1",
        ),
    );

    // list_clients method (query)
    schema.methods.insert(
        "list_clients".to_string(),
        method_decl_from_schemars_with_output::<ListClientsInput, ListClientsOutput>(
            "list_clients",
            SideEffect::Read,
            true,
            "emqx.read",
            "obs.net.emqx.clients.list@v1",
        ),
    );

    // get_client method (query)
    schema.methods.insert(
        "get_client".to_string(),
        method_decl_from_schemars_with_output::<GetClientInput, GetClientOutput>(
            "get_client",
            SideEffect::Read,
            true,
            "emqx.read",
            "obs.net.emqx.client.get@v1",
        ),
    );

    schema
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("emqx", |_ctx| std::sync::Arc::new(EmqxPlugin::new(EmqxConfig::default())))
}

