use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{ApplyResult, PluginCapabilities, StateAction, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::json;
use serde_json::Value as JsonValue;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::BTreeMap;
use std::path::Path;
use zbus::{Connection, Proxy};
use uuid::Uuid;
use chrono::Utc;

/// EMQX configuration.
/// See: https://docs.emqx.io/
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, Default)]
pub struct EmqxConfig {
    /// Enable EMQX broker
    pub enabled: bool,
    /// EMQX node name
    pub node: String,
    /// EMQX listener configuration
    pub listeners: Vec<EmqxListener>,
}

/// EMQX listener configuration.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxListener {
    /// Listener name (e.g., "tcp://0.0.0.0:1883")
    pub name: String,
    /// Whether the listener is enabled
    pub enabled: bool,
    /// Bind address
    pub bind: String,
    /// Maximum concurrent connections
    pub max_conns: Option<u32>,
}

/// EMQX node status.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxNodeStatus {
    /// Node name
    pub node: String,
    /// Node status (running, stopped, etc.)
    pub status: String,
    /// Node inet version (inet, inet6)
    pub inet: String,
    /// Node options
    pub options: String,
}

/// EMQX client information.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxClient {
    /// Client ID
    pub clientid: String,
    /// Username (if authenticated)
    pub username: Option<String>,
    Option<String>,
    /// Client IP address
    pub ipaddress: String,
    /// Client port
    pub port: u16,
    /// Protocol (MQTT, MQTT-SN, CoAP, etc.)
    pub proto: String,
    /// Connection timestamp
    pub connected_at: String,
    /// Disconnection timestamp (if disconnected)
    pub disconnected_at: Option<String>,
    /// Connection status
    pub connected: bool,
    /// Node the client is connected to
    pub node: String,
}

/// EMQX state.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmqxState {
    /// Software name (emqx)
    pub software: String,
    /// Version string
    pub version: String,
    /// Required dependencies
    pub dependencies: Vec<String>,
    /// Whether emqx is installed
    pub installed: bool,
    /// Whether the emqx service is running under s6
    pub daemon_running: bool,
    /// EMQX control socket used by the runtime
    pub control_socket: Option<String>,
    /// EMQX configuration
    pub config: EmqxConfig,
    /// Node status
    pub node_status: Option<EmqxNodeStatus>,
    /// Connected clients
    pub clients: Vec<EmqxClient>,
    /// Results of the last method call, keyed by method name.
    /// Used to return values from query methods via state.
    #[serde(default)]
    pub last_method_results: BTreeMap<String, JsonValue>,
}

pub struct EmqxPlugin {
    config: EmqxConfig,
}

impl EmqxPlugin {
    pub fn new(config: EmqxConfig) -> Self {
        Self { config }
    }

    /// Check if emqx is installed via direct file check (AGENTS.md §4: no subprocess bypasses)
    fn check_emqx_installed() -> Result<bool> {
        Ok(std::path::Path::new("/usr/bin/emqx").exists()
            || std::path::Path::new("/usr/local/bin/emqx").exists())
    }

    /// Check if emqx daemon is running via D-Bus
    fn check_daemon_running() -> Result<bool> {
        // This is a simplified version - in reality would be async
        // For now, we'll return false and let the runtime handle it
        Ok(false)
    }

    fn emqx_config_path() -> &'static str {
        "/etc/emqx/emqx.conf"
    }

    fn read_emqx_config() -> Result<JsonValue> {
        match std::fs::read_to_string(Self::emqx_config_path()) {
            Ok(content) => Ok(serde_json::from_str(&content)
                .with_context(|| "Failed to parse /etc/emqx/emqx.conf")?),
            Err(_) => Ok(serde_json::json!({})),
        }
    }

    fn write_emqx_config(mut config: JsonValue) -> Result<()> {
        if !config.is_object() {
            config = serde_json::json!({});
        }

        std::fs::create_dir_all("/etc/emqx")?;
        std::fs::write(
            Self::emqx_config_path(),
            serde_json::to_string_pretty(&config)?,
        )
        .context("Failed to write /etc/emqx/emqx.conf")?;
        Ok(())
    }

    fn restart_emqx() -> Result<()> {
        // This would normally call stop then start via D-Bus
        // For now, we'll just return Ok
        Ok(())
    }

    /// Get current node status (simplified)
    fn get_node_status(&self) -> Result<Option<EmqxNodeStatus>> {
        // This is a simplified implementation
        Ok(Some(EmqxNodeStatus {
            node: self.config.node.clone(),
            status: if self.config.enabled {
                "running".to_string()
            } else {
                "stopped".to_string()
            },
            inet: "inet".to_string(),
            options: "[]".to_string(),
        }))
    }

    /// Get current clients (simplified)
    fn get_clients(&self) -> Result<Vec<EmqxClient>> {
        // This is a simplified implementation
        Ok(vec![])
    }

    /// Build the current state
    fn current_state() -> EmqxState {
        let node = std::env::var("EMQX_NODE").unwrap_or_else(|_| "emqx@localhost".to_string());

        EmqxState {
            software: "emqx".to_string(),
            version: "5.0.0".to_string(),
            dependencies: vec!["net".to_string(), "s6".to_string()],
            installed: Self::check_emqx_installed().unwrap_or(false),
            daemon_running: Self::check_daemon_running().unwrap_or(false),
            control_socket: Some("/var/run/emqx/emqx.ctl".to_string()),
            config: EmqxConfig {
                enabled: false,
                node: node.clone(),
                listeners: vec![EmqxListener {
                    name: "tcp://0.0.0.0:1883".to_string(),
                    enabled: false,
                    bind: "0.0.0.0:1883".to_string(),
                    max_conns: Some(1024),
                }],
            },
            node_status: Self::get_node_status(&self).unwrap_or(None),
            clients: Self::get_clients(&self).unwrap_or_default(),
            last_method_results: BTreeMap::new(),
        }
    }
}

#[async_trait]
impl StatePlugin for EmqxPlugin {
    fn name(&self) -> &'static str {
        "emqx"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    /// Available only when the emqx binary is installed.
    fn is_available(&self) -> bool {
        std::path::Path::new("/usr/bin/emqx").exists()
            || std::path::Path::new("/usr/local/bin/emqx").exists()
    }

    fn unavailable_reason(&self) -> String {
        format!(
            "emqx binary not found in /usr/bin or /usr/local/bin"
        )
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = emqx_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let mut actions = Vec::new();
        let mut errors = Vec::new();

        // Deserialize current and desired states
        let current_state: EmqxState = match serde_json::from_value(current.clone()) {
            Ok(state) => state,
            Err(e) => {
                return Err(anyhow::anyhow!("Failed to parse current state: {}", e));
            }
        };
        let desired_state: EmqxState = match serde_json::from_value(desired.clone()) {
            Ok(state) => state,
            Err(e) => {
                return Err(anyhow::anyhow!("Failed to parse desired state: {}", e));
            }
        };

        // Handle method calls in the desired state
        if let Some(method_call) = desired.get("__method_call") {
            if let Some(method_obj) = method_call.as_object() {
                if let Some(method_name) = method_obj.get("method").and_then(|v| v.as_str()) {
                    let args = method_obj.get("args").cloned().unwrap_or_else(|| json!({}));
                    match method_name {
                        "start" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "start",
                                    "args": args
                                }),
                            });
                        }
                        "stop" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "stop",
                                    "args": args
                                }),
                            });
                        }
                        "restart" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_service".to_string(),
                                config: json!({
                                    "method": "restart",
                                    "args": args
                                }),
                            });
                        }
                        "list_clients" => {
                            // For query methods, we don't change state, but we'll store the result in the state
                            actions.push(StateAction::Create {
                                resource: "emqx_method".to_string(),
                                config: json!({
                                    "method": "list_clients",
                                    "args": args
                                }),
                            });
                        }
                        "get_client" => {
                            actions.push(StateAction::Create {
                                resource: "emqx_method".to_string(),
                                config: json!({
                                    "method": "get_client",
                                    "args": args
                                }),
                            });
                        }
                        _ => {
                            // Unknown method - ignore
                        }
                    }
                }
            }
        }

        // Check if emqx should be installed/enabled based on config
        let current_installed = current_state.installed;
        let desired_enabled = desired_state.config.enabled;

        if !current_installed && desired_enabled {
            actions.push(StateAction::Create {
                resource: "emqx_installation".to_string(),
                config: json!({
                    "action": "install_emqx",
                    "type": "system_package"
                }),
            });
        }

        // Handle service start/stop based on config.enabled
        if current_state.config.enabled != desired_state.config.enabled {
            if desired_state.config.enabled {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "start_service",
                        "service": "emqx"
                    }),
                });
            } else {
                actions.push(StateAction::Create {
                    resource: "emqx_service".to_string(),
                    config: json!({
                        "action": "stop_service",
                        "service": "emqx"
                    }),
                });
            }
        }

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: Default::default(),
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        // Detect service controller once for all operations
        let controller = match Self::detect_controller().await {
            Ok(ctrl) => Some(ctrl),
            Err(e) => {
                errors.push(format!("Failed to detect service controller: {}", e));
                None
            }
        };

        for action in &diff.actions {
            if let StateAction::Create { resource, config } = action {
                if resource == "emqx_installation" {
                    // Package installation requires PackageKit D-Bus or manual install per AGENTS.md §4
                    errors.push(
                        "EMQX package installation requires external PackageKit D-Bus or manual install (disabled per AGENTS.md §4). \
                         Run: apt-get install -y emqx".to_string(),
                    );
                    // Attempt to enable and start service via D-Bus regardless
                    if let Some(ref ctrl) = controller {
                        match ctrl.enable_and_start("emqx").await {
                            Ok(_) => {
                                changes_applied.push(
                                    "Enabled and started EMQX service via D-Bus".to_string(),
                                );
                            }
                            Err(e) => {
                                errors.push(format!(
                                    "Failed to enable/start EMQX service via D-Bus: {}",
                                    e
                                ));
                            }
                        }
                    }
                } else if resource == "emqx_service" {
                    let action = config.get("action").and_then(|v| v.as_str()).unwrap_or("");
                    let service = config.get("service").and_then(|v| v.as_str()).unwrap_or("");
                    if action == "start_service" && service == "emqx" {
                        // Start emqx service via D-Bus (s6)
                        match self.start_emqx_service().await {
                            Ok(_) => changes_applied.push("Started EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to start EMQX service: {}", e)),
                        }
                    } else if action == "stop_service" && service == "emqx" {
                        // Stop emqx service via D-Bus (s6)
                        match self.stop_emqx_service().await {
                            Ok(_) => changes_applied.push("Stopped EMQX service".to_string()),
                            Err(e) => errors.push(format!("Failed to stop EMQX service: {}", e)),
                        }
                    }
                } else if resource == "emqx_method" {
                    let method_name = config.get("method").and_then(|v| v.as_str()).unwrap_or("");
                    let args = config.get("args").cloned().unwrap_or_else(|| json!({}));
                    match method_name {
                        "start" => {
                            match self.start_emqx_service().await {
                                Ok(_) => {
                                    changes_applied.push("Started EMQX service via method call".to_string());
                                    // Store result in state
                                    // We'll handle this in the state update below
                                }
                                Err(e) => errors.push(format!("Failed to start EMQX service: {}", e)),
                            }
                        }
                        "stop" => {
                            match self.stop_emqx_service().await {
                                Ok(_) => {
                                    changes_applied.push("Stopped EMQX service via method call".to_string());
                                }
                                Err(e) => errors.push(format!("Failed to stop EMQX service: {}", e)),
                            }
                        }
                        "restart" => {
                            match self.restart_emqx().await {
                                Ok(_) => {
                                    changes_applied.push("Restarted EMQX service via method call".to_string());
                                }
                                Err(e) => errors.push(format!("Failed to restart EMQX service: {}", e)),
                            }
                        }
                        "list_clients" => {
                            match self.get_clients() {
                                Ok(clients) => {
                                    changes_applied.push("Retrieved EMQX client list".to_string());
                                    // Store result in state - we'll do this by updating the state directly
                                    // For now, we note that the client list was retrieved
                                }
                                Err(e) => errors.push(format!("Failed to get EMQX client list: {}", e)),
                            }
                        }
                        "get_client" => {
                            let clientid = args.get("clientid").and_then(|v| v.as_str()).unwrap_or("");
                            match self.get_client_by_id(clientid.to_string()) {
                                Ok(client) => {
                                    changes_applied.push(format!("Retrieved EMQX client {}", clientid));
                                }
                                Err(e) => errors.push(format!("Failed to get EMQX client {}: {}", clientid, e)),
                            }
                        }
                        _ => {
                            errors.push(format!("Unknown method: {}", method_name));
                        }
                    }
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<op_state::Checkpoint> {
