use tonic::{Request, Response, Status};
use crate::proto::emqx_service_server::Emqx;
use crate::proto::{
    Empty, ListClientsResponse, GetClientResponse,
};
use op_plugins::state_plugins::emqx::EmqxPlugin;
use std::sync::Arc;
use tokio::sync::Mutex;

pub struct EmqxAdapter {
    plugin: Arc<Mutex<EmqxPlugin>>,
}

impl EmqxAdapter {
    pub fn new(plugin: Arc<Mutex<EmqxPlugin>>) -> Self {
        Self { plugin }
    }
}

#[tonic::async_trait]
impl Emqx for EmqxAdapter {
    async fn list_clients(
        &self,
        _request: Request<Empty>,
    ) -> Result<Response<ListClientsResponse>, Status> {
        let plugin_lock = self.plugin.lock().await;
        let state = match plugin_lock.current_state().await {
            Ok(state) => state,
            Err(e) => {
                return Err(Status::internal(format!(
                    "Failed to get EMQX state: {}",
                    e
                )));
            }
        };

        let mut response = ListClientsResponse::default();
        response.clients = state.clients.into_iter().map(|c| {
            // Convert from our internal client representation to protobuf
            // This would need to be adjusted based on actual protobuf definitions
            crate::proto::EmqxClient {
                clientid: c.clientid,
                username: c.username.unwrap_or_default(),
                ipaddress: c.ipaddress,
                port: c.port as u32,
                proto: c.proto,
                connected_at: c.connected_at,
                disconnected_at: c.disconnected_at,
                connected: c.connected,
                node: c.node,
            }
        }).collect();

        Ok(Response::new(response))
    }

    async fn get_client(
        &self,
        request: Request<GetClientRequest>,
    ) -> Result<Response<GetClientResponse>, Status> {
        let req = request.into_inner();
        let clientid = req.clientid;

        let plugin_lock = self.plugin.lock().await;
        let state = match plugin_lock.current_state().await {
            Ok(state) => state,
            Err(e) => {
                return Err(Status::internal(format!(
                    "Failed to get EMQX state: {}",
                    e
                )));
            }
        };

        // Find the client
        let client = state.clients.into_iter()
            .find(|c| c.clientid == clientid);

        match client {
            Some(c) => {
                let mut response = GetClientResponse::default();
                response.client = Some(crate::proto::EmqxClient {
                    clientid: c.clientid,
                    username: c.username.unwrap_or_default(),
                    ipaddress: c.ipaddress,
                    port: c.port as u32,
                    proto: c.proto,
                    connected_at: c.connected_at,
                    disconnected_at: c.disconnected_at,
                    connected: c.connected,
                    node: c.node,
                });
                Ok(Response::new(response))
            }
            None => Err(Status::not_found(format!(
                "Client with ID '{}' not found",
                clientid
            ))),
        }
    }
}

